package price

// Total returns quantity times unit price in cents.
func Total(quantity, unitCents int) int { return quantity * unitCents }

// Discount subtracts a fixed amount, clamping the result to zero.
func Discount(total, cents int) int { return max(0, total-cents) }

func internalVersion() int { return 1 }

